package benchmarks

// The accuracy scorecard is generated by cmd/report; this test only pins the
// harness itself: the corpus loads, every adapter survives every title, and
// jhin scores 100% on the corpus it is contract-tested against (if this
// fails, the adapter or a normalizer broke — not the parser).

import "testing"

func TestHarness(t *testing.T) {
	corpus, err := LoadCorpus("../parser/testdata/golden.json")
	if err != nil {
		t.Fatal(err)
	}
	if len(corpus) < 1000 {
		t.Fatalf("corpus suspiciously small: %d entries", len(corpus))
	}
	for i := range Libraries {
		lib := &Libraries[i]
		s := Score(lib, corpus)
		t.Logf("%s: overall %.1f%%, errors %d", lib.Name, s.Overall()*100, s.Errors)
		if lib.Name == "jhin" {
			if s.Errors != 0 {
				t.Errorf("jhin errored on %d titles", s.Errors)
			}
			for _, f := range ScoredFields {
				if acc := s.Fields[f].Accuracy(); acc != 1.0 {
					for _, d := range Disagreements(lib, corpus, f) {
						t.Errorf("jhin %s mismatch on %q: gold %q/%v got %q/%v",
							f, d.Title, d.Gold, d.GoldS, d.Got, d.GotS)
						break
					}
					t.Errorf("jhin %s accuracy %.4f != 1.0 — harness adapter or normalizer bug", f, acc)
				}
			}
		}
	}
}
